window.kbPageData["views/entry/k-3feaca28aa7cc75f"] = {"key":"entry/k-3feaca28aa7cc75f","state":{"route":"entry/k-3feaca28aa7cc75f"},"node":{"id":"k-3feaca28aa7cc75f","mode":"k","title":"《现代化首都都市圈空间协同规划（2023—2035 年）》获批（2 月 2 日）","type":"事实与事件","domain":"公共管理","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["regional"],"主类":["事实与事件"],"出处性质":["时政汇编"],"学科":["公共管理"],"时间索引":["年度事件或数据"],"来源主题":["重要文件"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"《现代化首都都市圈空间协同规划（2023—2035 年）》获批（2 月 2 日）","slug":"97a8b8486115"}],"directorySummary":"考点一 《现代化首都都市圈空间协同规划（2023—2035 年）》获批（2 月 2 日）\n这是全国首个由中共中央、国务院批复的都市圈规划。规划以有序疏解北京非首都功能、解决\n北京“大城市病”为基本出发点，锚定优化提升和服务保障首都功能的重要地区、世界一流城\n市群建设主引擎、中华文明传承发展重要地区、…","sources":[{"id":"749420890a1aeef5","label":"《现代化首都都市圈空间协同规划（2023—2035 年）》获批（2 月 2 日）","topic":"重要文件","category":"时政","text":"考点一 《现代化首都都市圈空间协同规划（2023—2035 年）》获批（2 月 2 日）\n这是全国首个由中共中央、国务院批复的都市圈规划。规划以有序疏解北京非首都功能、解决\n北京“大城市病”为基本出发点，锚定优化提升和服务保障首都功能的重要地区、世界一流城\n市群建设主引擎、中华文明传承发展重要地区、区域协同治理引领区、美丽中国建设先行区的\n战略定位。发展目标：到 2030 年取得积极进展、到 2035 年构架基本形成、展望 2050 年全面\n建成；构建“一核两翼、双城多点、双廊多圈”空间格局（一核即北京，两翼为雄安新区和北\n京城市副中心，双城为北京、天津，双廊为京津、京雄走廊）。","source":{"doc":"4e539a366dce19555ccf","first":12,"last":12,"page":12,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"regional","title":"区域协调与城乡融合"}],"units":{"k-3feaca28aa7cc75f":[]}};
